// contexts/AuthContext.js
import React, { createContext, useContext, useReducer, useEffect } from 'react';
import { USER_STATES, AUTH_PROVIDERS } from '../types/auth';
import { mockAuthService } from '../services/mockAuthService';

const AuthContext = createContext();

const initialAuthState = {
  // Estado del usuario
  user: {
    id: null,
    email: null,
    name: null,
    username: null,
    avatar: null,
    city: null,
    provider: AUTH_PROVIDERS.ANONYMOUS,
    createdAt: null,
    lastLoginAt: null
  },
  
  // Estado de la sesión
  session: {
    isAuthenticated: false,
    isAnonymous: true,
    token: localStorage.getItem('trucoapp_token'),
    refreshToken: localStorage.getItem('trucoapp_refresh_token'),
    expiresAt: null,
    lastSync: null
  },
  
  // Estado de la aplicación
  app: {
    state: USER_STATES.ANONYMOUS,
    isLoading: false,
    error: null,
    migrationStatus: null,
    hasLocalData: false,
    needsSync: false,
    isOnline: navigator.onLine
  },
  
  // Configuración
  preferences: {
    syncEnabled: true,
    notificationsEnabled: false,
    darkMode: false,
    allowAnalytics: true
  }
};

const parseTokenExpiry = (token) => {
  try {
    // Mock token format: mock_token_userId_timestamp
    const parts = token.split('_');
    const timestamp = parseInt(parts[parts.length - 1]);
    return timestamp + (24 * 60 * 60 * 1000); // +24 horas
  } catch {
    return Date.now() + (24 * 60 * 60 * 1000);
  }
};

const authReducer = (state, action) => {
  switch (action.type) {
    case 'AUTH_LOADING':
      return {
        ...state,
        app: { ...state.app, isLoading: true, error: null }
      };
      
    case 'AUTH_SUCCESS':
      return {
        ...state,
        user: action.payload.user,
        session: {
          ...state.session,
          isAuthenticated: true,
          isAnonymous: false,
          token: action.payload.token,
          refreshToken: action.payload.refreshToken,
          expiresAt: action.payload.expiresAt
        },
        app: {
          ...state.app,
          state: USER_STATES.AUTHENTICATED,
          isLoading: false,
          error: null
        }
      };
      
    case 'AUTH_ERROR':
      return {
        ...state,
        app: {
          ...state.app,
          isLoading: false,
          error: action.payload.error
        }
      };
      
    case 'LOGOUT':
      // Limpiar tokens
      localStorage.removeItem('trucoapp_token');
      localStorage.removeItem('trucoapp_refresh_token');
      
      return {
        ...initialAuthState,
        preferences: state.preferences // Mantener preferencias
      };
      
    case 'SET_ANONYMOUS':
      return {
        ...state,
        app: {
          ...state.app,
          state: USER_STATES.ANONYMOUS,
          isLoading: false
        }
      };
      
    case 'START_MIGRATION':
      return {
        ...state,
        app: {
          ...state.app,
          state: USER_STATES.MIGRATING,
          migrationStatus: 'starting'
        }
      };
      
    case 'MIGRATION_COMPLETE':
      return {
        ...state,
        app: {
          ...state.app,
          state: USER_STATES.AUTHENTICATED,
          migrationStatus: 'completed',
          needsSync: false
        }
      };
      
    case 'UPDATE_PROFILE':
      return {
        ...state,
        user: {
          ...state.user,
          ...action.payload
        }
      };
      
    case 'SET_ONLINE_STATUS':
      return {
        ...state,
        app: {
          ...state.app,
          isOnline: action.payload
        }
      };
      
    default:
      return state;
  }
};

export const AuthProvider = ({ children }) => {
  const [state, dispatch] = useReducer(authReducer, initialAuthState);
  
  // Usar mock service por ahora (fácil de cambiar después)
  const api = mockAuthService;
  
  // Inicialización
  useEffect(() => {
    initializeAuth();
    
    // Monitor network status
    const handleOnline = () => dispatch({ type: 'SET_ONLINE_STATUS', payload: true });
    const handleOffline = () => dispatch({ type: 'SET_ONLINE_STATUS', payload: false });
    
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);
  
  const initializeAuth = async () => {
    try {
      dispatch({ type: 'AUTH_LOADING' });
      
      // Verificar token existente
      const token = localStorage.getItem('trucoapp_token');
      if (token) {
        try {
          const user = await api.verifyToken(token);
          dispatch({
            type: 'AUTH_SUCCESS',
            payload: {
              user,
              token,
              refreshToken: localStorage.getItem('trucoapp_refresh_token'),
              expiresAt: parseTokenExpiry(token)
            }
          });
          return;
        } catch (error) {
          // Token inválido, limpiar
          localStorage.removeItem('trucoapp_token');
          localStorage.removeItem('trucoapp_refresh_token');
        }
      }
      
      // Usuario anónimo por defecto
      dispatch({ type: 'SET_ANONYMOUS' });
      
    } catch (error) {
      console.error('Error initializing auth:', error);
      dispatch({ type: 'AUTH_ERROR', payload: { error: error.message } });
    }
  };
  
  return (
    <AuthContext.Provider value={{ state, dispatch, api }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuthContext = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuthContext must be used within AuthProvider');
  }
  return context;
};