// components/IOSContainer.jsx - Componente específico para iOS safe areas
import React from 'react';
import { useIOSViewport } from '../hooks/useIOSViewport';

const IOSContainer = ({ children, className = '' }) => {
  const { isIOS } = useIOSViewport();
  
  return (
    <div className={`
      h-screen-dynamic flex flex-col
      ${isIOS ? 'ios-safe-container' : 'flex flex-col h-screen'}
      ${className}
    `}>
      {children}
    </div>
  );
};

export const IOSContentArea = ({ children, className = '' }) => {
  return (
    <div className={`
      flex-1 overflow-y-auto ios-smooth-scroll
      ${className}
    `}>
      {children}
    </div>
  );
};

export const IOSTabBar = ({ children, className = '' }) => {
  return (
    <div className={`
      flex-shrink-0 ios-tab-bar
      bg-[#0a0a0a] border-t border-[#D4A574] border-opacity-30
      ${className}
    `}>
      {children}
    </div>
  );
};

export default IOSContainer;